package com.eventhub.service; import com.eventhub.dto.*; import com.eventhub.entity.*; import com.eventhub.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class NoticeService {private final NoticeRepository repo;private final UserRepository users;private final AuditLogService audit; @Transactional(readOnly=true) public Page<NoticeResponse> active(int page,int size){return repo.findByActiveTrueOrderByCreatedAtDesc(PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(NoticeResponse::from);} @Transactional(readOnly=true) public Page<NoticeResponse> all(String email,int page,int size){admin(email);return repo.findAllByOrderByCreatedAtDesc(PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(NoticeResponse::from);} @Transactional public NoticeResponse create(String email,NoticeRequest r,String ip){User u=admin(email);Notice n=repo.save(Notice.builder().title(r.title().trim()).content(r.content().trim()).priority(r.priority()).active(r.active()).createdBy(u).build());audit.log(u,"NOTICE_CREATED","NOTICE",n.getId(),ip,"Notice created");return NoticeResponse.from(n);} @Transactional public NoticeResponse update(String email,Long id,NoticeRequest r,String ip){User u=admin(email);Notice n=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Notice not found"));n.setTitle(r.title().trim());n.setContent(r.content().trim());n.setPriority(r.priority());n.setActive(r.active());audit.log(u,"NOTICE_UPDATED","NOTICE",id,ip,"Notice updated");return NoticeResponse.from(n);} @Transactional public void delete(String email,Long id,String ip){User u=admin(email);if(!repo.existsById(id))throw new IllegalArgumentException("Notice not found");repo.deleteById(id);audit.log(u,"NOTICE_DELETED","NOTICE",id,ip,"Notice deleted");} private User admin(String e){User u=users.findByEmailIgnoreCase(e).orElseThrow(()->new IllegalArgumentException("User not found"));if(u.getRole()!=Role.ADMIN&&u.getRole()!=Role.SUPER_ADMIN)throw new org.springframework.security.access.AccessDeniedException("Admin access required");return u;}}
